/**
 * Get system setup status.
 *
 * NOTE: This endpoint is unauthenticated by design.
 *
 * During first-time bootstrap there is no admin account yet, so frontend initialization must be
 * able to query setup progress before any login flow exists.
 *
 * Only bootstrap-safe status information should be returned by this endpoint.
 *
 */
export const getSetup = <ThrowOnError extends boolean = false>(
  options?: Options<GetSetupData, ThrowOnError>,
): RequestResult<GetSetupResponses, unknown, ThrowOnError> =>
  (options?.client ?? client).get<GetSetupResponses, unknown, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/setup',
    ...options,
  })

/**
 * Initialize system setup with admin account.
 *
 * NOTE: This endpoint is unauthenticated by design for first-time bootstrap.
 * Access is restricted to self-hosted editions (`COMMUNITY` and `ENTERPRISE`), one-time setup guards,
 * and init-password validation rather than user session authentication.
 *
 */
export const postSetup = <ThrowOnError extends boolean = false>(
  options: Options<PostSetupData, ThrowOnError>,
): RequestResult<PostSetupResponses, unknown, ThrowOnError> =>
  (options.client ?? client).post<PostSetupResponses, unknown, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/setup',
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  })

